contract InvMutTest {
    C c;

    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address recipient) public payable {
        require(recipient != address(0), "bad recipient");
        require(recipient != address(c), "recipient is c, self-transfer");

        uint256 cBalBefore = address(c).balance;
        uint256 recipientBalBefore = recipient.balance;
        bool isOwner = (address(this) == c.owner());

        bool reverted;
        c.withdrawAll(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 cBalAfter = address(c).balance;
        uint256 recipientBalAfter = recipient.balance;

        assert(
            (isOwner && !reverted && cBalAfter == 0 && recipientBalAfter == recipientBalBefore + cBalBefore)
            ||
            (!isOwner && reverted && cBalAfter == cBalBefore && recipientBalAfter == recipientBalBefore)
        );
    }

    receive() external payable {}
}

